/**
 * Server-side lookup of every place in the atlas, built from
 * src/lib/catalog-index.json (generated by scripts/build-catalog-index.mjs).
 *
 * Saved places take their name, category, state, road system and points from
 * here — never from the browser — so points and badges can't be faked.
 */

export type CatalogEntry = {
  id: string;
  name: string;
  category: string;
  sys: string;
  points: number;
  /** Every state the place is listed under (more than one for multi-state drives). */
  states: string[];
};

type IndexFile = {
  v: number;
  groups: Record<string, { prefix: string; rows: [string, string, number][] }>;
};

let byId: Map<string, CatalogEntry> | null = null;
let loading: Promise<Map<string, CatalogEntry>> | null = null;

async function load() {
  if (byId) return byId;
  loading ??= import("@/lib/catalog-index.json").then((mod) => {
    const file: IndexFile = mod.default;
    const map = new Map<string, CatalogEntry>();
    for (const [key, group] of Object.entries(file.groups)) {
      const [category = "", state = "", sys = ""] = key.split("|");
      for (const [raw, name, points] of group.rows) {
        const id = raw.startsWith("=") ? raw.slice(1) : group.prefix + raw;
        const hit = map.get(id);
        if (hit) {
          if (!hit.states.includes(state)) hit.states.push(state);
          continue;
        }
        map.set(id, { id, name, category, sys, points, states: [state] });
      }
    }
    byId = map;
    return map;
  });
  return loading;
}

export async function lookupPlace(id: string): Promise<CatalogEntry | null> {
  return (await load()).get(id) ?? null;
}

/** The state in the id (p:drive:IL:route66 → IL) when the place is listed there, else its first state. */
function homeState(entry: CatalogEntry) {
  const fromId = entry.id.split(":").find((part) => entry.states.includes(part));
  return fromId ?? entry.states[0] ?? "";
}

/**
 * The trusted version of a saved place. `state` is the client's choice only
 * when the place really is listed in that state; otherwise its first state.
 */
export async function canonicalPlace(id: string, state?: string) {
  const entry = await lookupPlace(id);
  if (!entry) return null;
  return {
    name: entry.name,
    category: entry.category,
    sys: entry.sys,
    points: entry.points,
    state: state && entry.states.includes(state) ? state : homeState(entry),
  };
}
